// Filters the navigation per role so each person sees only their workspace.
// UI decluttering only (per-browser, stored in localStorage) — NOT access
// control: the app still has one shared password and one shared database.

const cur = () => {
  const p = localStorage.getItem('nav_profile');
  const allowed = (window._ACC && Array.isArray(window._ACC.profiles) && window._ACC.profiles.length) ? window._ACC.profiles : (window._ACC && window._ACC.profile ? [window._ACC.profile] : null);
  if (allowed && allowed.indexOf('management') < 0) return (allowed.indexOf(p) >= 0) ? p : allowed[0];
  return PROFILES[p] ? p : 'management';
};
function apply() {
  const name = cur();
  const prof = PROFILES[name];
  const sel = document.getElementById('nav-profile');
  if (sel) sel.value = name;
  const wsAllowed = (window._ACC && Array.isArray(window._ACC.profiles) && window._ACC.profiles.length) ? window._ACC.profiles : (window._ACC && window._ACC.profile ? [window._ACC.profile] : null);
  const canSwitch = !wsAllowed || wsAllowed.indexOf('management') >= 0 || wsAllowed.length > 1;
  if (sel) sel.style.display = canSwitch ? '' : 'none';
  if (sel && wsAllowed) Array.prototype.forEach.call(sel.options, function (o) {
    o.hidden = wsAllowed.indexOf('management') < 0 && wsAllowed.indexOf(o.value) < 0;
  });
  // main tabs
  document.querySelectorAll('.nav-btn[data-tab]').forEach(b => {
    const t = b.dataset.tab;
    const show = (t === 'home' || (name === 'accountant' && t === 'perf') || prof.tabs === 'all' || prof.tabs.includes(t)) && (typeof accTab !== 'function' || accTab(t));
    b.style.display = show ? '' : 'none';
  });
  // tools dropdown items
  let toolsVisible = 0;
  document.querySelectorAll('.nav-dd-item[data-tab]').forEach(b => {
    const show = (prof.tools === 'all' || prof.tools.includes(b.dataset.tab)) && (typeof accTab !== 'function' || accTab(b.dataset.tab));
    b.style.display = show ? '' : 'none';
    if (show) toolsVisible++;
  });
  const dd = document.getElementById('nav-dd');
  if (dd) dd.style.display = toolsVisible ? '' : 'none';
  // management-only chrome
  const clearBtn = document.getElementById('btn-clear-all');
  if (clearBtn) clearBtn.style.display = name === 'management' ? '' : 'none';
  // Operator is a finance-free view: no revenue totals, no property counts
  const totals = document.getElementById('dash-totals');
  if (totals) totals.style.display = name === 'operator' ? 'none' : '';
  if (typeof _opsSchedRepaint === 'function') { try { _opsSchedRepaint(); } catch (e) {} }
  const hdrProps = document.getElementById('hdr-props');
  if (hdrProps) hdrProps.style.display = name === 'operator' ? 'none' : '';
  // dashboard quick-action shortcuts follow the profile too
  document.querySelectorAll('#tab-dash button[onclick*="showTab"]').forEach(b => {
    const m = String(b.getAttribute('onclick') || '').match(/showTab\('(\w+)'/);
    if (!m) return;
    const t = m[1];
    const ok = (prof.tabs === 'all' || prof.tabs.includes(t)) || (prof.tools === 'all' || (Array.isArray(prof.tools) && prof.tools.includes(t))) && (typeof accTab !== 'function' || accTab(t));
    b.style.display = ok ? '' : 'none';
  });
  // if the open tab is now hidden, fall back to the Dashboard
  const act = document.querySelector('.tab-panel.active');
  const actName = act ? act.id.replace(/^tab-/, '') : 'dash';
  const allowed = t => t === 'home' || (name === 'accountant' && t === 'perf') || (typeof accTab !== 'function' || accTab(t)) && ((PROFILES[name].tabs === 'all' || PROFILES[name].tabs.includes(t)) ||
                       (PROFILES[name].tools === 'all' || PROFILES[name].tools.includes(t)));
