    const dashBtn = document.querySelector('.nav-btn[data-tab="dash"]');
    if (typeof showTab === 'function') showTab('dash', dashBtn);
  }
}
window.setNavProfile = function (v) {
  localStorage.setItem('nav_profile', PROFILES[v] ? v : 'management');
  apply();
  if (typeof renderDashActions === 'function') { try { renderDashActions(); } catch (e) {} }
  if (typeof toast === 'function') {
    const L = { operator: 'Operations workspace', accountant: 'Accounting workspace', management: 'Admin workspace' };
    toast(L[cur()] + ' — the menu shows only what this role needs. Switch back anytime.');
  }
};

